"""Generate docs/STRESS_CREDIBILITY.md from results/stress_{dt,search,faults}.json."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
R = ROOT / "results"
dt = json.loads((R / "stress_dt.json").read_text())
se = json.loads((R / "stress_search.json").read_text())
fa = json.loads((R / "stress_faults.json").read_text())


def ci(r):
    lo, hi = r["p_violation_ci95"]
    return f"{r['p_violation']:.2f} ({lo:.2f} to {hi:.2f})"


L = ["# Stress credibility", "",
     "Generated by `scripts/make_stress_credibility_doc.py` from `results/stress_dt.json`, "
     "`stress_search.json` and `stress_faults.json` (`scripts/stress_credibility.py`). Do not edit by hand. "
     "All figures are simulated with the model in `sirb/disturbance.py` and carry its assumptions; "
     "they are not flight data. Predictions and their grading are in `docs/PREDICTIONS.md` (P25 to P27).", "",
     "## 1. Frame step convergence", "",
     f"Show `{dt['show']}`, {dt['trials']} trials per cell, evaluation seed {dt['seed']}. "
     "Median minimum separation is in metres.", "",
     "| Configuration | Step (s) | P(violation) (95% Wilson) | Median min separation (m) |", "|---|---|---|---|"]
for r in dt["rows"]:
    L.append(f"| {r['config']} | {r['dt']} | {ci(r)} | {r['min_separation_quantiles']['0.5']:.3f} |")
L += ["", "## 2. Worst case search", "",
      f"Show `{se['show']}` (nominal minimum separation {se['nominal_min_separation_m']:.3f} m, threshold "
      f"{se['d_min_m']} m). Searched box: " + "; ".join(f"{k} {a} to {b}" for k, (a, b) in se["box"].items()) + ". "
      f"Each method used {se['evaluations_per_method']} evaluations of {se['trials_per_evaluation']} trials on "
      f"tuning seed {se['seed_tune']}; the returned configuration was then evaluated on {se['eval_trials']} trials "
      f"of separate seed {se['seed_eval']}. The tuning objective is the median minimum separation (lower is worse for the plan).", "",
      f"Reference with every disturbance off: P(violation) {ci(se['benign_default'])}.", "",
      "| Method | Tuning objective (m) | Evaluation P(violation) | Best parameters |", "|---|---|---|---|"]
for k in ("random", "evolution"):
    r = se[k]
    prm = ", ".join(f"{a} {b:.2f}" for a, b in r["best_params"].items())
    L.append(f"| {r['method']} | {r['tuning_objective_median_min_sep_m']:.3f} | {ci(r['evaluation'])} | {prm} |")
L += ["", "A configuration found inside the declared box that breaks the plan shows the plan is not robust over "
      "that box. It does not show how likely such a configuration is in operation.", "",
      "## 3. Fault matrix with detection delay", "",
      f"Show `{fa['show']}` (nominal minimum separation {fa['nominal_min_separation_m']:.3f} m), "
      f"{fa['trials']} trials per row, seed {fa['seed']}. Detection delay is the time between a fault "
      "starting and the contingency behaviour starting.", "",
      "| Case | P(violation) (95% Wilson) | Mean violating pairs | Involving an event drone | Among uninvolved drones | Class |",
      "|---|---|---|---|---|---|"]
for r in fa["rows"]:
    L.append(f"| {r['case']} | {ci(r)} | {r['mean_violating_pairs']:.2f} | "
             f"{r['p_violation_involving_event_drone']:.2f} | {r['p_violation_between_bystanders']:.2f} | {r['outcome']} |")
L += ["", "Class rule: no violation observed if the upper interval bound is at most 0.05; violations involve an "
      "event drone if the rate among uninvolved drones is at most 0.05; otherwise uninvolved drones too. "
      "The combined row has many violating pairs on average, so its class label understates how widespread it is.", ""]
(ROOT / "docs" / "STRESS_CREDIBILITY.md").write_text("\n".join(L))
